import React, { useState } from 'react';
import {
    View,
    Text,
    TouchableOpacity,
    ActivityIndicator,
} from 'react-native';

import { ParamListBase, useNavigation } from '@react-navigation/native';
import { NativeStackNavigationProp } from '@react-navigation/native-stack';

import { useContexState } from '../../hooks/context';
import { useLoadPage } from '../../hooks/loadPage';
import { styles } from './styles';

import api from '../../services/api';

type YourNavigatorProps = NativeStackNavigationProp<ParamListBase, keyof ParamListBase>

interface CardsProps {
    position: number;
    listItemProps: {
        data: { firstCard: number, id: string };
        list?: {
            [key: string]: [{
                id: number;
                name: string;
                phone: string;
                price: number;
                analyzed: number;
            }]
        };
    };
};

interface response {
    data: {
        id: number;
        number: number;
        name: string;
        phone: string;
        price: number;
        analyzed: number;
    }[]
};


export function CardNumber({ listItemProps, position }: CardsProps) {
    const [checkBuyLoad, setCheckBuyLoad] = useState(false)
    const cardNumber = listItemProps.data.firstCard + position;

    const {
        isMountedApi,
        shoppingCartItem,
        listData
    } = useContexState();

    const {
        setSelectedNumber,
        setAlertActive,
        setPaymentMenuActive,
        setAlertMessage
    } = useContexState();

    const { LoadPage } = useLoadPage();

    const tempShoppingCartItem = [...shoppingCartItem];
    const index = tempShoppingCartItem.indexOf(cardNumber);
    const navigation = useNavigation<YourNavigatorProps>();

    function colorSelect() {
        if (shoppingCartItem[index]) {
            return { backgroundColor: '#7B68EE' };
        };

        if (listItemProps.list?.[String(cardNumber)]) {
            return {
                backgroundColor: listItemProps.list?.
                [cardNumber][0].analyzed !== 0 ? '#26A744' : '#17A2B7'
            };
        } else {
            return {
                backgroundColor: '#fff',
                color: '#121212'
            };
        };
    };


    function checkBuy() {
        setCheckBuyLoad(true);

        function AlertMessageSelect() {
            if (shoppingCartItem[index]) {
                return 'O número já está no carrinho!';
            };

            if (listItemProps.list?.[cardNumber][0].analyzed === 0) {
                return 'O número já foi comprado!';
            } else {
                return 'O número está em análise!';
            };
        };

        function ResponceClick(responce: response) {
            setCheckBuyLoad(false)
            if (!listItemProps.list?.[String(cardNumber)] && responce.data.length === 0) {
                setPaymentMenuActive(true);
                setSelectedNumber(cardNumber);
            } else if (listItemProps.list?.[String(cardNumber)] && responce.data.length !== 0) {
                setAlertActive(true);
                setAlertMessage(AlertMessageSelect());
            };

            if (listItemProps.list?.[String(cardNumber)] && responce.data.length === 0) {
                LoadPage(Number(listData[0]?.firstCard));
            } else if (!listItemProps.list?.[String(cardNumber)] && responce.data.length !== 0) {
                LoadPage(Number(listData[0]?.firstCard));
            };
        };

        api.get("getCards", {
            params: {
                firstNumber: cardNumber,
                lastNumber: cardNumber,
            }
        }).then(ResponceClick);
    };


    function ButtonCard() {
        return cardNumber <= 9999 && cardNumber >= 0 ? (
            <TouchableOpacity
                onPress={() => isMountedApi ? checkBuy() : null}
                style={{ alignItems: 'center', justifyContent: 'center' }}>
                <Text
                    style={[styles.listText, colorSelect()]}>
                    {(`0000${cardNumber}`).slice(-4)}
                </Text>
                {!isMountedApi || checkBuyLoad ?
                    <ActivityIndicator
                        style={{ position: 'absolute' }}
                        size={20}
                        color='#121212'
                    /> : null}
            </TouchableOpacity>
        ) : <View />
    };

    return <ButtonCard />;
};
